content.text:
                return (left + right) % modulus
            return (left - right) % modulus
        raise ExpressionError('unknown binary operator: ' + str(op))


#: Symbol spellings accepted by :func:`compile_expression` in addition to the
#: documented operator names.
_OPERATOR_ALIASES = {
    '==': 'eq', '!=': 'ne', '<': 'lt', '<=': 'le', '>': 'gt', '>=': 'ge',
    '+': 'add', '-': 'sub', '&': 'and', '|': 'or',
}

_RELATIONS = frozenset(('eq', 'ne', 'lt', 'le', 'gt', 'ge'))
_ARITHMETIC = frozenset(('add', 'sub'))
_CONNECTIVES = frozenset(('and', 'or', 'implies'))


def static_value(expr):
    """Return the value of a purely constant expression, else ``None``."""
    if isinstance(expr, Const):
        return expr.constant
    if isinstance(expr, Binop) and expr.type is not None and \
            isinstance(expr.type, Int) and expr.op in _ARITHMETIC:
        left = static_value(expr.left)
        right = static_value(expr.right)
        if left is None or right is None:
            return None
        modulus = expr.type.modulus
        return ((left + right) if expr.op == 'add' else (left - right)) % modulus
    return None


def compile_expression(node, scope, types, patterns=None):
    """Compile a JSON expression array against a lexical scope of types.

    ``scope`` maps visible variable names to their (alias-resolved) types;
    ``types`` maps declared type names to type objects.
    """
    if patterns is None:
        patterns = {}
    return _compile(node, scope, types, patterns)


def _compile(node, scope, types, patterns):
    if not isinstance(node, list) or not node:
        raise ExpressionError('expression must be a non-empty array')
    head = node[0]
    if head == 'var':
        if len(node) != 2:
            raise ExpressionError('var takes one name')
        name = node[1]
        if name not in scope:
            raise ExpressionError('unbound variable ' + str(name))
        return Var(Type.inner(scope[name]), name)
    if head == 'const':
        if len(node) != 3:
            raise ExpressionError('const takes a type and a value')
        type_name, value = node[1], node[2]
        if type_name not in types:
            raise ExpressionError('unknown type ' + str(type_name))
        return Const(Type.inner(types[type_name]), value)
    if head == 'field':
        if len(node) != 3:
            raise ExpressionError('field takes a value and a field name')
        base = _compile(node[1], scope, types, patterns)
        struct = base.type
        if not isinstance(struct, Struct):
            raise ExpressionError('field expression expected struct type')
        if node[2] not in struct.fields:
            raise ExpressionError('unknown field ' + str(node[2]))
        return Field(Type.inner(struct.fields[node[2]]), base, node[2])
